package com.forgeci.application.github;
import com.forgeci.application.auth.AuthException; import com.forgeci.application.security.FieldEncryptionService; import com.forgeci.domain.repository.GitHubConnection; import com.forgeci.infrastructure.repository.GitHubConnectionRepository; import com.forgeci.infrastructure.user.UserRepository; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import java.time.Instant; import javax.crypto.Mac; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class GitHubConnectionService { private final GitHubClient github; private final GitHubConnectionRepository connections; private final UserRepository users; private final FieldEncryptionService encryption; private final byte[] stateSecret; public GitHubConnectionService(GitHubClient g,GitHubConnectionRepository c,UserRepository u,FieldEncryptionService e,@Value("${forgeci.github.state-secret}") String s){github=g;connections=c;users=u;encryption=e;stateSecret=s.getBytes(StandardCharsets.UTF_8);if(stateSecret.length<32)throw new IllegalArgumentException("GitHub state secret must be at least 32 characters");} public String authorizeUrl(UUID userId){String payload=userId+":"+Instant.now().getEpochSecond()+":"+UUID.randomUUID();return github.authorizationUrl(payload+":"+sign(payload));} @Transactional public void callback(UUID expectedUserId,String state,String code) throws Exception {String[] p=state.split(":");if(p.length!=4||!p[0].equals(expectedUserId.toString()))throw new AuthException("INVALID_OAUTH_STATE","Invalid GitHub OAuth state");long issued=Long.parseLong(p[1]);if(Instant.now().getEpochSecond()-issued>600||!MessageDigest.isEqual(sign(p[0]+":"+p[1]+":"+p[2]).getBytes(StandardCharsets.UTF_8),p[3].getBytes(StandardCharsets.UTF_8)))throw new AuthException("INVALID_OAUTH_STATE","Invalid GitHub OAuth state");var token=github.exchangeCode(code).accessToken();var gh=github.currentUser(token);var user=users.findById(expectedUserId).orElseThrow(()->new AuthException("USER_NOT_FOUND","User not found"));var cipher=encryption.encrypt(token);var existing=connections.findByUserId(expectedUserId);if(existing.isPresent()){existing.get().replaceToken(gh.id(),gh.login(),cipher);connections.save(existing.get());}else connections.save(new GitHubConnection(user,gh.id(),gh.login(),cipher));} @Transactional public void disconnect(UUID userId){connections.findByUserId(userId).ifPresent(c->{c.disconnect();connections.save(c);});} public String token(UUID userId){var c=connections.findByUserId(userId).filter(GitHubConnection::isActive).orElseThrow(()->new AuthException("GITHUB_NOT_CONNECTED","GitHub is not connected"));return encryption.decrypt(c.getAccessTokenCiphertext());} public GitHubConnection connection(UUID userId){return connections.findByUserId(userId).orElseThrow(()->new AuthException("GITHUB_NOT_CONNECTED","GitHub is not connected"));} private String sign(String p){try{var m=Mac.getInstance("HmacSHA256");m.init(new javax.crypto.spec.SecretKeySpec(stateSecret,"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(p.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
